  {
    "id": "ContactNode",
    "type": "object",
    "description": "A node representing a contact in an address book.",
    "properties": {
      "id": {
        "type": "string",
        "description": "The unique identifier for the node. IDs are unique within the current profile, and they remain valid even after the program is restarted."
      },
      "parentId": {
        "type": "string",
        "optional": true,
        "description": "The ``id`` of the parent object."
      },
      "type": {
        "$ref": "addressBooks.NodeType",
        "description": "Always set to <value>contact</value>."
      },
      "readOnly": {
        "type": "boolean",
        "optional": true,
        "description": "Indicates if the object is read-only."
      },
      "remote": {
        "type": "boolean",
        "optional": true,
        "description": "Indicates if the object came from a remote address book."
      },
      "properties": {
        "max_manifest_version": 2,
        "$ref": "ContactProperties"
      },
      "vCard": {
        "min_manifest_version": 3,
        "type": "string"
      }
    }
  },
  {
    "id": "ContactProperties",
    "type": "object",
    "description": "A set of individual properties for a particular contact, and its vCard string. Further information can be found in :doc:`examples/vcard`.",
    "patternProperties": {
      "^\\w+$": {
        "choices": [
          {
            "type": "string"
          },
          {
            "type": "null"
          }
        ]
      }
    }
  },
  {
    "id": "PropertyChange",
    "type": "object",
    "description": "A dictionary of changed properties. Keys are the property name that changed, values are an object containing ``oldValue`` and ``newValue``. Values can be either a string or <value>null</value>.",
    "patternProperties": {
      "^\\w+$": {
        "type": "object",
        "properties": {
          "oldValue": {
            "choices": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ]
          },
          "newValue": {
            "choices": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ]
          }
        }
      }
    }
  }
],
"functions": [
  {
    "name": "list",
    "type": "function",
    "async": "callback",
    "parameters": [
      {
        "name": "parentId",
        "type": "string"
      },
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "type": "array",
            "items": {
              "$ref": "ContactNode"
            }
          }
        ]
      }
    ],
    "description": "Gets all the contacts in the address book with the id ``parentId``."
  },
  {
    "name": "quickSearch",
    "max_manifest_version": 2,
    "type": "function",
    "async": "callback",
    "parameters": [
      {
        "name": "parentId",
        "type": "string",
        "optional": true,
        "description": "The id of the address book to search. If not specified, all address books are searched."
      },
      {
        "name": "queryInfo",
        "description": "Either a <em>string</em> with one or more space-separated terms to search for, or a complex :ref:`contacts.QueryInfo` search query.",
        "choices": [
          {
            "type": "string"
          },
          {
            "$ref": "QueryInfo"
          }
        ]
      },
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "type": "array",
            "items": {
              "$ref": "ContactNode"
            }
          }
        ]
      }
    ],
    "description": "Gets all contacts matching ``queryInfo`` in the address book with the id ``parentId``."
  },
  {
    "name": "query",
    "min_manifest_version": 3,
    "type": "function",
    "async": "callback",
    "parameters": [
      {
        "name": "queryInfo",
        "$ref": "QueryInfo"
      },
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "type": "array",
            "items": {
              "$ref": "ContactNode"
            }
          }
        ]
      }
    ],
    "description": "Gets all contacts matching ``queryInfo``."
  },
  {
    "name": "get",
    "type": "function",
    "async": "callback",
    "parameters": [
      {
        "name": "id",
        "type": "string"
      },
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "$ref": "ContactNode"
          }
        ]
      }
    ],
    "description": "Gets a single contact."
  },
  {
    "name": "getPhoto",
    "type": "function",
    "async": "callback",
    "parameters": [
      {
        "name": "id",
        "type": "string"
      },
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "choices": [
              {
                "type": "object",
                "isInstanceOf": "File",
                "additionalProperties": true
              },
              {
                "type": "null"
              }
            ]
          }
        ]
      }
    ],
    "description": "Gets the photo associated with this contact. Returns <value>null</value>, if no photo is available."
